  ::selection { background: var(--yellow); color: var(--black); }

  .page { max-width: 1120px; margin: 0 auto; }

  /* top bar: black band, white text — one horizontal line at the top */
  .topbar {
    background: var(--black);
    color: var(--white);
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 14px 28px;
    font-weight: 600;
    font-size: 13px;
    letter-spacing: 0.14em;
    text-transform: uppercase;
  }
  .topbar .sq { display: inline-flex; gap: 6px; margin-right: 12px; vertical-align: -1px; }
