    grid-template-columns: 150px 1fr;
    gap: 16px;
    padding: 10px 0;
    border-bottom: 2px solid var(--black);
    font-size: 15px;
  }
  .facts .row dt { font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; font-size: 12px; color: var(--grey); padding-top: 2px; }
  .facts .row dd { font-weight: 500; }

