  .composition {
    aspect-ratio: 4 / 3;
    background: var(--black);
    display: grid;
    grid-template-columns: 0.65fr 1.3fr 0.7fr 1.55fr;
    grid-template-rows: 1.5fr 1fr;
    gap: var(--line);
    padding: var(--line);
    max-width: 520px;
    width: 100%;
    margin-left: auto;
  }
  .composition i { display: block; }
  .c-white { background: var(--white); }
